const questSteps = [
 {label:'Make it playable',family:'Development',title:'The first minute is confusing.',body:'Your tester keeps walking past the seed box. The team has time for one improvement today. What do you try?',options:[['Make the goal visible and test again.','You chose to test a clearer signal. A visible goal can help, but watch a new player before assuming it works.','critical thinking'],['Add a beautiful new garden area.','A new area might add delight. It won’t necessarily explain the seed box, so keep the first-minute question on the test list.','creative exploration'],['Ask where the tester expected to find seeds.','You made room for the player’s perspective instead of labeling them “bad at games.” Their answer can guide a small prototype.','empathy']],roles:'Game designer + artist + programmer + player researcher',lesson:'Start with the intended experience, prototype early, observe and revise.'},
 {label:'Keep it fair',family:'Monetization',title:'How will the work be paid for?',body:'The team needs a way to support development. Your audience includes people with different budgets. Choose a model to investigate, then consider its trade-off.',options:[['A free demo, with a clearly priced full game.','Players can try before deciding. Show exactly what the demo includes and the full price. The team still needs to test whether enough players will buy.','transparent communication'],['One upfront price, with no paid advantages.','A clear one-time price can be easy to understand. It may still exclude some players, so consider accessibility, regional context and legitimate low-cost access options.','fairness thinking'],['Optional cosmetic purchases with clear prices.','Cosmetics can help fund a game, but “optional” does not automatically mean fair. Avoid pressure, confusing currencies and targeting vulnerable players. Budget and age-appropriate safeguards matter.','ethical trade-offs']],roles:'Economy designer + product analyst + producer + community team',lesson:'A good business decision should consider both studio sustainability and player trust.'},
 {label:'Help it reach people',family:'Distribution',title:'A great game still needs a clear doorway.',body:'You have a tiny budget and limited time. What should your first release preparation focus on?',options:[['A small test release with accurate device requirements.','A limited test can reveal compatibility and access problems before a bigger launch. State what works, what doesn’t and how people can stop participating.','practical planning'],['A short trailer showing real play.','A truthful trailer helps players understand the experience. Make captions readable and make sure the footage represents features that actually exist.','honest storytelling'],['Clear controls, content information and support notes.','You’re helping players make an informed choice. Include device needs, access options and known limits. A clear page still needs a realistic way for people to find it.','inclusive communication']],roles:'Publishing producer + marketing creative + localization + QA',lesson:'Distribution is about reaching people and making the path into play understandable.'},
 {label:'Listen with care',family:'Player sentiment',title:'Five loud comments. The whole story?',body:'A few comments say the garden is “too slow.” Other players are quiet. How do you learn what to do next?',options:[['Ask a neutral question and test with more people.','You treated feedback as a clue, not a verdict. Ask what felt slow, observe where it happened, and include people who don’t post publicly.','curiosity and empathy'],['Use an AI sentiment summary, then check the examples.','A summary can help organize a large set, but sarcasm, slang and mixed feelings can be misread. Use invented or authorized data, inspect examples and do not label an individual’s emotions as fact.','verification'],['Make one small change and invite a comparison.','A reversible change creates a useful test. Define what you want to learn, watch for side effects and explain what is still uncertain.','iteration and resilience']],roles:'Player researcher + community specialist + product analyst',lesson:'Sentiment is evidence about expressed reactions, not mind-reading or a vote from every player.'}
];
const aiScenarios=[
 {title:'You need a poster for your paper game.',body:'You have one sketch, a simple title and a short deadline. What is a thoughtful starting point?',options:[['Use your sketch and a reusable layout.','That may meet the need without generation. Reuse reduces extra work; check legibility and asset permissions. “No AI” is a valid design decision.'],['Generate 40 image variations immediately.','Pause and define the missing piece first. A large batch may use resources without helping you decide. Try a sketch or one small test, then stop when it works.'],['Write a clear brief, then decide if AI adds value.','A useful habit. If you do use generation, request only what you need, review the output and avoid endless variations. There is no universal footprint number for this choice.']]},
 {title:'A tool gives you a confident game-history fact.',body:'It includes a quote and a source name. You want to put it in your project.',options:[['Use it because it sounds specific.','Specific detail can still be invented. Find the actual source, check the quote in context and remove it if you cannot verify it.'],['Find the original source and check the claim.','You practiced verification. Compare the wording, date and context, and save the source link. A generated citation is not itself evidence.'],['Ask the same tool “are you sure?”','That can prompt a revision, but it is not an independent check. The system may repeat the same error. Look for a reliable original source.']]},
 {title:'You want to understand player feedback.',body:'A friend offers a private group chat with names and personal stories. You are making a workshop example.',options:[['Upload the whole chat to a sentiment tool.','Don’t upload other people’s private conversations. Permission, service terms and privacy matter. Use invented comments for this exercise instead.'],['Make a small set of invented comments.','A safer practice choice. Label them as fictional, manually group themes, then compare any automated result with the examples.'],['Ask AI to tell you who is angry.','A model cannot know someone’s inner feelings from text. Discuss the wording and uncertainty instead of assigning emotional labels to people.']]},
 {title:'AI suggests code for your game.',body:'It seems to work once. You want to call the feature done.',options:[['Ship it because the tool wrote it.','You are still responsible for the result. Test normal and unusual inputs, inspect dependencies and avoid using secrets or private code in prompts.'],['Test, explain and simplify it.','Strong practice. If you cannot explain the code, learn the small piece first. Test edge cases and check the source or license of reused material.'],['Regenerate until one version looks convincing.','Appearance is not correctness. Define a test, investigate the failure and change one thing at a time. Repeated guessing can waste effort and computation.']]}
];
 const AI_AVOID={0:[1],1:[0,2],2:[0,2],3:[0,2]},AI_SAFE={0:2,1:1,2:1,3:1};
 function aiNote(i,a){const sc=aiScenarios[i],o=sc.options[a];if((AI_AVOID[i]||[]).includes(+a)){const safe=sc.options[AI_SAFE[i]];return sc.title+' ⚠ A choice to avoid: '+o[0]+' Why: '+o[1]+' Safer choice: '+safe[0]}return sc.title+' My choice: '+o[0]}

