function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function go(page, focus=true){window.kollabArrivalMovie?.stop();if(!$('#page-'+page))return;state.page=page;document.body.classList.toggle('home-surface',page==='home');state.visited.add(page);$$('.page').forEach(p=>{const a=p.id==='page-'+page;p.hidden=!a;p.classList.toggle('active',a)});$$('[data-page]').forEach(b=>{const a=b.dataset.page===page;b.classList.toggle('active',a);if(a)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});history.replaceState(null,'','#'+page);window.scrollTo({top:0,behavior:'instant'});if(focus){const h=$('#page-'+page+' h1');h.tabIndex=-1;h.focus({preventScroll:true})}if(page==='plan')renderPlan();}
function motionBehavior(){return document.body.classList.contains('reduced-motion')||matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}
function focusUpdate(container,feedback=false){const root=$(container);const target=feedback?$('.feedback h3',root)||$('h2,h3',root):$('h2,h3',root);if(target){target.tabIndex=-1;target.focus({preventScroll:true});target.scrollIntoView({block:'nearest',behavior:motionBehavior()})}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(html){$('#dialog-content').innerHTML=html;$('#detail-dialog').showModal();$('#detail-dialog .dialog-close').focus()}
function confetti(){if(document.body.classList.contains('reduced-motion')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const box=document.createElement('div');box.className='confetti';box.setAttribute('aria-hidden','true');for(let i=0;i<24;i++){const el=document.createElement('i');el.style.left=(Math.random()*100)+'%';el.style.animationDelay=(Math.random()*.4)+'s';box.append(el)}document.body.append(box);setTimeout(()=>box.remove(),2400)}
function boost(){const b=boosts[state.boost++%boosts.length];modal(`<div class="boost-card"><span class="eyebrow">A KOLLAB CO-OP BOOST</span><span class="boost-icon" aria-hidden="true">✳</span><h2>${b[0]}</h2><p>${b[1]}</p><h3>${b[2]}</h3><p class="tiny">No ranking. No streak. Just an invitation to keep exploring.</p><button class="button primary" data-close>Keep exploring →</button></div>`);confetti()}
function renderInterests(){ $('#interests').innerHTML=interests.map(i=>`<button class="interest" data-interest="${i[0]}" aria-pressed="${state.interests.has(i[0])}"><span class="interest-icon" aria-hidden="true">${i[1]}</span>${i[2]}</button>`).join('');$('#selection-count').textContent=`${state.interests.size} of 3 interests selected`;const picked=interests.filter(i=>state.interests.has(i[0]));$('#signal-title').textContent=picked.length?'A starting point, not a box.':'Curiosity counts.';$('#signal-copy').textContent=picked.length?picked.map(i=>i[3]).join(' '):'You don’t need to know your dream job. Notice what you like doing, then try one small thing.';$('#match-title').textContent=picked.length?'Some doors to try first.':'Explore all four sides.';renderRoles()}
function renderRoles(){const ordered=roles.map((r,i)=>({...r,score:r.tags.filter(t=>state.interests.has(t)).length,order:i})).filter(r=>state.filter==='all'||r.family===state.filter).sort((a,b)=>b.score-a.score||a.order-b.order);let shown=ordered;if(!state.roleExpanded){shown=!state.interests.size&&state.filter==='all'?Object.keys(familyNames).map(f=>ordered.find(r=>r.family===f)):ordered.slice(0,3)}$('#role-grid').innerHTML=shown.map(r=>`<article class="role-card"><div class="role-top"><span class="family-tag">${familyNames[r.family]}</span>${r.score?'<span class="fit-tag">Interest connection ✦</span>':''}</div><h3>${r.name}</h3><p>${r.work}</p>${r.score?`<div class="role-match">Connects with ${r.tags.filter(t=>state.interests.has(t)).map(t=>interests.find(i=>i[0]===t)[2].toLowerCase()).join(' + ')}</div>`:''}<div class="role-footer"><button class="text-button" data-role="${r.id}">Look inside →</button><button class="save-small ${state.missions.has(r.id)?'saved':''}" data-mission="${r.id}">${state.missions.has(r.id)?'In this tab ✓':'+ Choose a mission'}</button></div></article>`).join('');$('#role-results-note').textContent=state.roleExpanded?`${shown.length} roles to explore. This is not a ranking of your ability.`:`${shown.length} places to start. Every role is still open to you.`;$('#show-more-roles').hidden=ordered.length<=shown.length&&!state.roleExpanded;$('#show-more-roles').textContent=state.roleExpanded?'Show a few starting points':`Explore all ${ordered.length} ${state.filter==='all'?'roles':'in this area'}`;$('#show-more-roles').setAttribute('aria-expanded',state.roleExpanded)}

function roleDetail(id){const r=roles.find(r=>r.id===id);if(!r)return;modal(`<span class="eyebrow dialog-eyebrow">${familyNames[r.family]} / ROLE EXPLORER</span><h2>${r.name}</h2><p>${r.work}</p><h3>Future-facing skills</h3><p>${r.future}</p><h3>Try it: ${r.mission}</h3><p class="tiny">${r.time} · Paper or phone notes works</p><ol>${r.steps.map(x=>`<li>${x}</li>`).join('')}</ol><h3>Keep this piece of proof</h3><p>${r.proof}</p><h3>If you want to go further</h3><p>${r.next}</p><button class="button primary" data-mission="${r.id}">${state.missions.has(r.id)?'Mission saved ✓':'Add this mission to my plan →'}</button><p class="tiny">Exploration, not a test or a job promise. Titles and responsibilities vary by studio.</p>`)}
function missionData(id){const r=roles.find(r=>r.id===id);return r?{name:r.mission,time:r.time,steps:r.steps,proof:r.proof}:extraMissions[id]}
const missionTemplates=JSON.parse(JSON.stringify(extraMissions));
function captureMission(id){
 const base=missionTemplates[id];if(!base)return;
 let notes=[];
 if(id==='studio-quest')notes=state.answers.flatMap((a,i)=>a===undefined?[]:[questSteps[i].family+': '+(a===null?'Explored without choosing':questSteps[i].options[a][0]),...(state.questNotes[i]?['My note: '+state.questNotes[i]]:[])]);
 if(id==='ai-audit')notes=Object.entries(state.aiAnswers).map(([i,a])=>aiNote(i,a));
 if(id==='usc-prototype')notes=['My route: '+uscRoutes[state.usc].name,uscRoutes[state.usc].practice,'My audience goal: '+audiences[state.audience][0],audiences[state.audience][1]];
 if(notes.length)extraMissions[id]={...base,steps:[...notes,...(id==='usc-prototype'?base.steps.slice(1):base.steps)]};
}
function saveMission(id){captureMission(id);if(!missionData(id))return;if(state.missions.has(id)){renderPlan();toast('Your plan now includes these choices.');return}state.missions.set(id,{complete:false});$('#saved-count').textContent=state.missions.size;renderRoles();renderPlan();$$(`[data-mission="${id}"]`).forEach(b=>{if(!b.classList.contains('text-button'))b.textContent='In this tab ✓'});toast('Added in this tab only. Download your plan before leaving.');if(state.missions.size===1)confetti()}
function renderPlan(){const list=$('#mission-list');list.innerHTML=[...state.missions].map(([id,s])=>{const m=missionData(id);return `<article class="mission-card ${s.complete?'complete':''}"><div class="mission-top"><div><span class="mission-time">${m.time.toUpperCase()} · PAPER / PHONE NOTES</span><h3>${m.name}</h3></div><button class="remove-mission" data-remove="${id}" aria-label="Remove ${esc(m.name)}">×</button></div><ol>${m.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="output"><b>Keep:</b> ${m.proof}</p><label><input type="checkbox" data-complete="${id}" ${s.complete?'checked':''}> I tried this. My first version counts.</label></article>`}).join('');$('#empty-plan').hidden=state.missions.size>0;$('#plan-total').textContent=state.missions.size?`${state.missions.size} mission${state.missions.size===1?'':'s'} · ${[...state.missions.values()].filter(x=>x.complete).length} tried`:'Your mission list';$('#saved-count').textContent=state.missions.size;updateExportButtons()}
function updateExportButtons(){const empty=state.missions.size===0&&!Object.values(state.reflection).some(Boolean)&&!state.answers.length;$('#download-plan').disabled=empty;$('#print-plan').disabled=empty}
function downloadPlan(){const lines=['KOLLAB YOUTH · MY NEXT-LEVEL PLAN','A starting point, not a prediction.','',...(state.interests.size?['Interests I explored: '+interests.filter(i=>state.interests.has(i[0])).map(i=>i[2]).join(', '),'']:[])];[...state.missions].forEach(([id,s],i)=>{const m=missionData(id);lines.push(`${i+1}. ${m.name} (${m.time})`,...m.steps.map((x,j)=>`   ${j+1}) ${x}`),`Keep: ${m.proof}`,`Tried: ${s.complete?'Yes':'Not yet'}`,'')});if(state.answers.length){lines.push('STUDIO CHOICES');state.answers.forEach((a,i)=>{if(a!==undefined)lines.push(questSteps[i].family+': '+(a===null?'Explored without choosing':questSteps[i].options[a][0]),'My reason / question: '+(state.questNotes[i]||'Not added'))});lines.push('')}lines.push('MY OPTIONAL PROCESS NOTES','My contribution: '+(state.reflection.made||'Not added'),'What I observed: '+(state.reflection.observed||'Not added'),'One revision: '+(state.reflection.revised||'Not added'),'My next step: '+(state.reflection.next||'Not added'),'When: '+(state.reflection.when||'Not chosen'),'Support that would help: '+(state.reflection.support||'Not chosen'),'','Ask a trusted person for feedback. No need to share names or personal information.','USC is one possible pathway, not the only route. Verify current requirements on official pages.','USC Games degrees: https://games.usc.edu/degrees','Viterbi applications: https://viterbiadmission.usc.edu/apply/','SCA Game Development: https://cinema.usc.edu/admissions/procedures/interactive/firstyearprocedures.cfm','Kollab Youth: https://kollabyouth.org/','','Independent educational experience. Research checked November 6, 2026.');const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='my-kollab-next-level-plan.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your plan is ready to keep. No information was uploaded.')}
function renderQuest(){const done=state.quest>=questSteps.length;$('#quest-steps').innerHTML=questSteps.map((q,i)=>`<li class="${i===state.quest?'current':i<state.quest?'done':''}"><span class="step-num">${i<state.quest?'✓':i+1}</span>${q.label}</li>`).join('');if(done){const practices=state.answers.map((a,i)=>a===null?'exploring without a fixed answer':questSteps[i].options[a][2]);$('#quest-content').innerHTML=`<span class="eyebrow">SURPRISE / THE CREDITS WERE HIDING IN YOUR CHOICES</span><h2>You helped a game become<br><span class="text-lime">more thoughtful.</span></h2><p>You explored four kinds of work that make a game possible. Your choices opened conversations, not a score.</p><div class="reward-row">${practices.map(x=>`<span class="reward-badge">Practiced: ${x}</span>`).join('')}</div><div class="quest-recap">${questSteps.map((q,i)=>`<div class="recap-row"><b>${q.family.toUpperCase()}</b><p>${state.answers[i]===null?'You chose to explore this step without selecting an answer.':q.options[state.answers[i]][0]}</p></div>`).join('')}</div><p><b>That is Kollab energy:</b> collaboration, communication, creativity and learning by trying.</p><div class="button-row"><button class="button primary" data-mission="studio-quest">Turn this into a real tiny project →</button><button class="button outline" id="restart-quest">Review my choices →</button></div>`;return}const q=questSteps[state.quest];const answered=state.answers[state.quest]!==undefined;const selected=state.answers[state.quest];$('#quest-content').innerHTML=`<span class="eyebrow">${state.quest+1} / 4 · ${q.family.toUpperCase()}</span><h2>${q.title}</h2><p>${q.body}</p><div class="option-list">${q.options.map((o,i)=>`<button class="option ${answered?(selected===i?'selected':'muted'):''}" data-quest-answer="${i}" ${answered?'disabled':''}>${o[0]}</button>`).join('')}</div>${answered?`<div class="feedback"><h3>${selected===null?'Exploring is enough.':'Here’s the trade-off.'}</h3><p>${selected===null?q.lesson:q.options[selected][1]}</p><p class="role-reveal"><b>Who works on this?</b><br>${q.roles}</p></div><details><summary>Add a note (optional)</summary><label class="quest-reason-label">My reason or remaining question <span>(optional, in this tab only)</span><textarea rows="2" maxlength="180" data-quest-reason="${state.quest}" dir="auto" placeholder="A trade-off I noticed…">${esc(state.questNotes[state.quest]||'')}</textarea></label></details><div class="button-row"><button class="button primary" id="next-quest">${state.quest===3?'Reveal my studio credits ✦':'Next decision →'}</button><button class="text-button" id="change-quest">Change my choice</button></div>`:'<button class="text-button" id="skip-quest">Explore this step without choosing →</button>'}`}
function renderAI(){ $('#ai-tabs').innerHTML=aiScenarios.map((s,i)=>`<button data-ai-tab="${i}" class="${i===state.ai?'active':''}" aria-label="Scenario ${i+1}: ${esc(s.title)}" aria-pressed="${i===state.ai}">${state.aiAnswers[i]!==undefined?'✓':i+1}</button>`).join('');const s=aiScenarios[state.ai],ans=state.aiAnswers[state.ai];$('#ai-scenario').innerHTML=`<span class="eyebrow">SCENARIO ${state.ai+1} OF ${aiScenarios.length}</span><h3>${s.title}</h3><p>${s.body}</p><div class="option-list">${s.options.map((o,i)=>`<button class="option ${ans===i?'selected':''}" data-ai-answer="${i}">${o[0]}</button>`).join('')}</div>${ans!==undefined?`${(AI_AVOID[state.ai]||[]).includes(ans)?`<div class="feedback ai-avoid"><h3>⚠ A choice to avoid</h3><p>${s.options[ans][1]}</p><p><b>Safer choice:</b> ${s.options[AI_SAFE[state.ai]][0]}</p></div>`:`<div class="feedback"><h3>A decision worth thinking through.</h3><p>${s.options[ans][1]}</p></div>`}<div class="button-row">${state.ai===aiScenarios.length-1?'<button class="button outline" id="finish-ai">Keep my choices →</button>':'<button class="button outline" id="next-ai">Next scenario →</button>'}<button class="text-button" data-mission="ai-audit">Save an AI practice mission →</button></div>`:'<p class="tiny">Choose an option to unpack it. You can explore every response.</p>'}`}
function renderUSC(){ $('#usc-tabs').innerHTML=uscRoutes.map((r,i)=>`<button class="usc-tab ${i===state.usc?'active':''}" id="route-tab-${i}" role="tab" aria-selected="${i===state.usc}" aria-controls="usc-detail" data-usc="${i}"><span>${r.degree.toUpperCase()}</span>${r.short}</button>`).join('');const r=uscRoutes[state.usc];$('#usc-detail').setAttribute('role','tabpanel');$('#usc-detail').setAttribute('aria-labelledby','route-tab-'+state.usc);$('#usc-detail').innerHTML=`<div><span class="route-pill">${r.degree}</span><h3>${r.name}</h3><p><b>${r.prompt}</b></p><p>${r.what}</p><div class="detail-section"><h4>Try the work in 5 minutes</h4><p>${r.practice}</p></div><button class="button primary" data-mission="usc-prototype">Save this exploration →</button></div><div><div class="detail-section"><h4>Your first piece of evidence</h4><p>${r.evidence}</p></div><div class="detail-section"><h4>Application reality check</h4><p>${r.admissions}</p><a href="${r.url}" target="_blank" rel="noopener">Read this program’s official instructions →</a></div><p class="tiny">The activity is an original workshop prompt, not an official USC assignment, admissions assessment or promise of access.</p></div>`}
function sources(){modal(`<span class="eyebrow dialog-eyebrow">READ FURTHER / CREDITS</span><h2>Grounded in real sources.</h2><p>Official pages were checked November 6, 2026. This independent guide combines those facts with original educational activities. Evolving roles are possibilities to explore, not labor-market forecasts.</p><ul class="source-list"><li><a href="https://kollabyouth.org/youth-registration" target="_blank" rel="noopener">Kollab Youth program values</a><small>Collaboration, creativity, empathy, communication, initiative and resilience inform the encouragement in this experience.</small></li><li><a href="https://games.usc.edu/degrees" target="_blank" rel="noopener">USC Games degree and minor overview</a><small>Undergraduate routes across Cinematic Arts and Viterbi; use program-level admissions pages for current application rules.</small></li><li><a href="https://cinema.usc.edu/admissions/procedures/interactive/firstyearprocedures.cfm" target="_blank" rel="noopener">SCA Game Development application</a> · <a href="https://viterbiadmission.usc.edu/apply/" target="_blank" rel="noopener">Viterbi application</a><small>Separate school processes. This experience deliberately avoids hard-coded deadlines because umbrella and school-level pages can differ.</small></li><li><a href="https://financialaid.usc.edu/undergraduate-financial-aid/cost-of-attendance/" target="_blank" rel="noopener">USC cost of attendance</a> · <a href="https://affordability.usc.edu/" target="_blank" rel="noopener">Affordability initiative</a><small>Published budgets are before aid, not a personal quote. Eligibility matters.</small></li><li><a href="https://www.uscgamesexpo.com/" target="_blank" rel="noopener">USC Games Expo</a> · <a href="https://games.usc.edu/summer-bridge" target="_blank" rel="noopener">Summer Bridge eligibility</a><small>The 2026 Expo is a past showcase. Summer Bridge serves selected current/recent USC students, not general high-school access.</small></li><li><a href="https://www.gamedeveloper.com/design/book-excerpt-game-design-workshop" target="_blank" rel="noopener">Tracy Fullerton: Game Design Workshop excerpt</a><small>Playcentric design: intended experience, early prototype, observation, revision and retesting. Used as a design principle, not an official USC lesson.</small></li><li><a href="https://www.iea.org/reports/key-questions-on-energy-and-ai/executive-summary" target="_blank" rel="noopener">IEA: Key Questions on Energy and AI</a><small>Data-center electricity demand, which includes more than AI. Environmental effects vary; the site makes no per-prompt carbon claims.</small></li><li><a href="https://www.screenskills.com/job-profiles/browse/games/" target="_blank" rel="noopener">ScreenSkills games career profiles</a><small>Role descriptions and industry structure. Our tiny missions are original learning exercises, not hiring criteria.</small></li><li><a href="https://wedocs.unep.org/items/5f3afe87-5419-439b-a6ee-14240b2605e9" target="_blank" rel="noopener">UNEP: AI’s environmental lifecycle</a><small>Environmental considerations extend beyond electricity to materials, infrastructure and water.</small></li><li><a href="https://www.unesco.org/en/articles/ai-competency-framework-students?hub=66973" target="_blank" rel="noopener">UNESCO student AI competency framework</a><small>Human-centered understanding, ethics and responsible skill-building.</small></li><li><a href="https://learn.microsoft.com/en-us/xbox/sustainability/xbox-game-energy-efficiency-essentials" target="_blank" rel="noopener">Xbox game energy-efficiency essentials</a><small>Energy-aware development is an evolving practical skill, not a guaranteed new job title.</small></li><li><a href="https://www.nist.gov/itl/ai-risk-management-framework" target="_blank" rel="noopener">NIST AI Risk Management Framework</a><small>Useful context for verification, risk and responsible use.</small></li><li><a href="https://gameaccessibilityguidelines.com/" target="_blank" rel="noopener">Game Accessibility Guidelines</a><small>Practical design checks; no checklist guarantees universal access.</small></li><li><a href="https://twinery.org/" target="_blank" rel="noopener">Twine</a> · <a href="https://mitscratch.freshdesk.com/en/support/solutions/articles/4000156776-can-i-use-scratch-on-my-phone-or-tablet-" target="_blank" rel="noopener">Scratch device guidance</a><small>Paper/phone notes are the default. Most phones play but do not create Scratch projects.</small></li><li><a href="https://www.smc.edu/academics/academic-departments/design-technology/game-design-foundation.php" target="_blank" rel="noopener">Santa Monica College Game Design Foundation</a><small>Another learning route to investigate with a counselor, not a guaranteed USC transfer pipeline.</small></li></ul><h3>Creative credits</h3><p>Original concept, world illustrations and optional opening animation created with Higgsfield. Original 3D island modeled and rendered in Blender. Companion checkpoint-card designs created in Canva. These are imaginative visuals, not depictions of USC facilities or promises of an actual program.</p><p class="tiny">The game Common Ground and all scenario comments are fictional. No youth names, personal stories or private facilitator material appear here.</p>`)}
function privacy(){modal(`<span class="eyebrow dialog-eyebrow">YOUR SPACE TO EXPLORE</span><h2>Low pressure. Local choices.</h2><p>This experience does not ask for your name, age, email, school, finances, photos, voice or private messages. There are no ads, analytics scripts, accounts inside the activity or AI model calls.</p><p>Your selections and optional fictional game / process notes live only in this open page’s memory. Closing or reloading resets them. Do not type names, contact details, health, family or other private information into the creative fields. Downloads happen on your device. This activity has no student account or sign-in form. External links open other sites with their own policies.</p><h3>Access options</h3><ul><li>Use keyboard, mouse or touch. No drag-only tasks, timers or sound-dependent instructions.</li><li>Use the motion button in the header to turn off decorative movement. Your system’s reduced-motion preference is also respected.</li><li>Skip studio choices, revisit chapters and explore every AI answer without a score.</li><li>All making activities have a paper or phone-notes route. No new tool account or AI subscription is required.</li><li>Use the print / save PDF button for a simple offline plan.</li></ul><p>Accessibility is ongoing work. This page is designed to reduce common barriers, but has not been certified for every assistive technology.</p>`)}
// A shared goal connects the USC routes into one collaborative prototype.
function addUSCWorkshop(){const box=document.createElement('section');box.className='section-pad';box.innerHTML=`<div class="section-heading"><div><span class="eyebrow">CO-OP UNLOCK / MAKE ONE WELCOME MOMENT</span><h2>Four doors. One shared world.</h2></div><p>The same goal can use every kind of contribution.</p></div><div class="scenario-card"><h3>A new player should feel welcome in 30 seconds.</h3><p>Choose an audience, then adapt the route activity above. This is a creative prompt, not a demographic profile.</p><div class="filters" id="audience-options"><button class="filter active" data-audience="new" aria-pressed="true">New to games</button><button class="filter" data-audience="quiet" aria-pressed="false">Prefers quiet</button><button class="filter" data-audience="phone" aria-pressed="false">On a small screen</button><button class="filter" data-audience="time" aria-pressed="false">Has five minutes</button></div><div class="feedback" id="audience-feedback"><h3>Make the first action clear.</h3><p>Use a visible goal, an optional hint and a way to try again. Ask your tester: “What did you think you could do?”</p></div><div class="button-row"><button class="button outline" id="co-op-unlock">Reveal the teammate I need ✦</button><button class="text-button" data-mission="usc-prototype">Keep a first version →</button></div></div>`;const s=$('#page-usc');s.insertBefore(box,s.children[3]);
const more=document.createElement('section');more.className='section-pad';more.innerHTML=`<div class="section-heading"><div><span class="eyebrow">THE TEAM GETS BIGGER</span><h2>Curiosity can cross disciplines.</h2></div></div><p>USC undergraduate minors include Game Design, Game Audio, Game Entrepreneurism, Game User Research, Video Game Production, Video Game Programming, Technical Game Art and Themed Entertainment. These are university study options, not public short courses or automatic add-ons to every degree.</p><div class="three-grid"><article class="explore-card"><span>SEE THE WORK</span><h3>Student games & the Expo</h3><p>USC’s Expo showcases student work, including Advanced Games Projects and MFA thesis projects. The 2026 Expo took place in May; explore it as a past showcase, not an upcoming invitation.</p><a href="https://www.uscgamesexpo.com/" target="_blank" rel="noopener">Explore the Expo site →</a></article><article class="explore-card"><span>UNDERSTAND ACCESS</span><h3>Summer Bridge ≠ high-school access</h3><p>USC Games Summer Bridge is an incubator for selected current/recent USC students. It should not be treated as an open high-school bridge program.</p><a href="https://games.usc.edu/summer-bridge" target="_blank" rel="noopener">Check official eligibility →</a></article><article class="explore-card"><span>KEEP OPTIONS OPEN</span><h3>More than one route</h3><p>Santa Monica College’s Game Design Foundation offers an associate degree or certificate. Ask a counselor about fit and transfer requirements; it is not an automatic USC pathway.</p><a href="https://www.smc.edu/academics/academic-departments/design-technology/game-design-foundation.php" target="_blank" rel="noopener">Explore SMC’s program →</a></article></div>`;s.insertBefore(more,s.lastElementChild);
const cost=document.createElement('details');cost.innerHTML=`<summary>5. Understand the published budget and aid</summary><p>For 2026–27, USC lists undergraduate tuition of $75,384 for two full-time semesters and an on-campus estimated total of $103,162 before aid, plus a $450 first-semester new-student fee. These are dated planning figures, not a personal quote or a future-year forecast.</p><p>USC’s affordability initiative states that eligible new first-year students from U.S. families earning $80,000 or less with typical assets can attend tuition-free. Tuition-free is not the same as all expenses paid. Eligibility and applications matter.</p><p>Use official estimators with a trusted adult or counselor. Do not enter family finances into this activity.</p><a href="https://financialaid.usc.edu/undergraduate-financial-aid/cost-of-attendance/" target="_blank" rel="noopener">Current published costs →</a> · <a href="https://financialaid.usc.edu/undergraduate-financial-aid/calculate-your-costs/" target="_blank" rel="noopener">Cost estimators →</a>`;$('.checkpoints').append(cost);
}
const audiences={new:['Make the first action clear.','Use a visible goal, an optional hint and a way to try again. Ask your tester: “What did you think you could do?”'],quiet:['Make quiet participation a real option.','Offer a written or visual path, keep audio optional and avoid putting someone on the spot. Ask: “Could you participate in the way you wanted?”'],phone:['Design for a small window.','Keep text readable, touch targets generous and the next action obvious. Don’t make dragging the only control. Ask: “What was hard to see or reach?”'],time:['Give a complete small experience.','Choose one meaningful action, a clear stopping point and no penalty for leaving. Ask: “Did you know what you could finish?”']};
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;
 if(b.dataset.station){const stations={art:['Make one shape feel welcoming.','Sketch a doorway that says “you can come in.” Use shape, not only color. What would you change for someone new to this world?','game-art'],logic:['A tiny rule is a building block.','Write one IF / THEN rule for a friendly game. Test what happens when someone repeats the action. Can they recover from a mistake?','programming'],sound:['A sound can tell a story.','Describe a sound for finding a hidden path. Then invent a visual cue that communicates the same thing with sound off.','audio'],community:['Make room for another way in.','Invent one way to join a team without speaking out loud. How would someone know they are welcome to try it?','accessibility']};const x=stations[b.dataset.station];modal(`<span class="eyebrow dialog-eyebrow">KOLLAB CREATIVE STATION</span><span class="boost-icon" aria-hidden="true">✦</span><h2>${x[0]}</h2><p>${x[1]}</p><button class="button primary" data-mission="${x[2]}">Save the full mini-mission →</button><p class="tiny">Paper, phone notes or your imagination is enough to start.</p>`)}
 if(b.dataset.page)go(b.dataset.page);if(b.dataset.go)go(b.dataset.go);if(b.matches('.wordmark')){e.preventDefault();go('home')}
 if(b.dataset.interest){state.roleExpanded=false;const id=b.dataset.interest;if(state.interests.has(id))state.interests.delete(id);else if(state.interests.size<3)state.interests.add(id);else{toast('Choose up to three for now. Tap one again to swap it.');return}renderInterests();$(`[data-interest="${id}"]`).focus()}
 if(b.dataset.filter){state.filter=b.dataset.filter;state.roleExpanded=false;$$('[data-filter]').forEach(x=>{const a=x.dataset.filter===state.filter;x.classList.toggle('active',a);x.setAttribute('aria-pressed',a)});renderRoles()}
 if(b.id==='show-more-roles'){state.roleExpanded=!state.roleExpanded;renderRoles();$('#show-more-roles').focus()}
 if(b.dataset.role)roleDetail(b.dataset.role);if(b.dataset.mission)saveMission(b.dataset.mission);
 if(b.dataset.remove){state.missions.delete(b.dataset.remove);renderPlan();renderRoles();toast('Mission removed. You can add it again anytime.')}
 if(b.dataset.questAnswer!==undefined){state.answers[state.quest]=Number(b.dataset.questAnswer);renderQuest();focusUpdate('#quest-content',true)}
 if(b.id==='skip-quest'){state.answers[state.quest]=null;renderQuest();focusUpdate('#quest-content',true)}
 if(b.id==='next-quest'){state.quest++;renderQuest();if(state.quest===4)confetti();focusUpdate('#quest-content')}
 if(b.id==='change-quest'){state.answers[state.quest]=undefined;renderQuest();focusUpdate('#quest-content')}
 if(b.id==='restart-quest'){state.quest=0;renderQuest();focusUpdate('#quest-content')}
 if(b.dataset.aiTab!==undefined){state.ai=Number(b.dataset.aiTab);renderAI();$(`[data-ai-tab="${state.ai}"]`).focus()}
 if(b.dataset.aiAnswer!==undefined){state.aiAnswers[state.ai]=Number(b.dataset.aiAnswer);renderAI();focusUpdate('#ai-scenario',true)}
 if(b.id==='finish-ai'){saveMission('ai-audit');go('plan')}
 if(b.id==='next-ai'){state.ai=(state.ai+1)%aiScenarios.length;renderAI();focusUpdate('#ai-scenario')}
 if(b.dataset.usc!==undefined){state.usc=Number(b.dataset.usc);renderUSC();$(`[data-usc="${state.usc}"]`).focus()}
 if(b.dataset.audience){state.audience=b.dataset.audience;$$('[data-audience]').forEach(x=>{const a=x.dataset.audience===state.audience;x.classList.toggle('active',a);x.setAttribute('aria-pressed',a)});const a=audiences[state.audience];$('#audience-feedback').innerHTML=`<h3>${a[0]}</h3><p>${a[1]}</p>`}
 if(b.id==='co-op-unlock'){const r=uscRoutes[state.usc];modal(`<span class="eyebrow dialog-eyebrow">KOLLAB CO-OP UNLOCK</span><span class="boost-icon" aria-hidden="true">✦</span><h2>Your idea gets stronger with a teammate.</h2><p>You’re exploring <b>${r.focus}</b>. Now add a player researcher: someone who asks a neutral question and notices where the experience is unclear.</p><h3>Swap roles. Both contributions count.</h3><p>One person makes, one tests, then switch. Working solo? Try both paths and write what you still don’t know. No one has to perform or share publicly.</p><p class="tiny">You just connected a creative role with a listening role. That is collaboration in action.</p><button class="button primary" data-close>Back to my prototype →</button>`);confetti()}
 if(b.id==='home-boost'||b.id==='plan-boost')boost();if(b.id==='sources-button')sources();if(b.id==='privacy-button')privacy();if(b.classList.contains('dialog-close')||b.hasAttribute('data-close'))$('#detail-dialog').close();
 if(b.id==='download-plan')downloadPlan();if(b.id==='print-plan')window.print();
 if(b.id==='clear-plan'){modal('<span class="eyebrow dialog-eyebrow">RESET THIS SESSION</span><h2>Start fresh?</h2><p>This clears your interest selections, missions and activity choices. Download your plan first if you want to keep it.</p><div class="button-row"><button class="button outline" data-close>Keep my progress</button><button class="button primary" id="confirm-reset">Reset my session</button></div>')}
 if(b.id==='confirm-reset'){Object.keys(missionTemplates).forEach(id=>extraMissions[id]=JSON.parse(JSON.stringify(missionTemplates[id])));state.interests.clear();state.missions.clear();delete extraMissions['my-first-scene'];state.quest=0;state.answers=[];state.questNotes=['','','',''];state.aiAnswers={};state.ai=0;state.usc=0;state.audience='new';state.boost=0;state.filter='all';state.roleExpanded=false;state.reflection={made:'',observed:'',revised:'',next:'',when:'',support:''};$$('[data-reflection]').forEach(x=>x.value='');$$('[data-reflection-print]').forEach(x=>x.textContent='Not added');$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter==='all');x.setAttribute('aria-pressed',x.dataset.filter==='all')});renderInterests();renderPlan();renderQuest();renderAI();renderUSC();$$('[data-audience]').forEach(x=>{const a=x.dataset.audience==='new';x.classList.toggle('active',a);x.setAttribute('aria-pressed',a)});$('#audience-feedback').innerHTML='<h3>'+audiences.new[0]+'</h3><p>'+audiences.new[1]+'</p>';$('#detail-dialog').close();toast('Fresh start. Curiosity still counts.')}
 if(b.id==='motion-toggle'){const reduced=document.body.classList.toggle('reduced-motion');b.setAttribute('aria-pressed',reduced);toast(reduced?'Decorative motion is off.':'Decorative motion follows your device settings.')}
});
document.addEventListener('change',e=>{if(e.target.dataset.complete){const completedId=e.target.dataset.complete;const s=state.missions.get(e.target.dataset.complete);s.complete=e.target.checked;renderPlan();$(`[data-complete="${completedId}"]`).focus();if(s.complete)toast('You tried something. That is evidence you can build on.')}});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#usc-tabs').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();state.usc=e.key==='Home'?0:e.key==='End'?3:(state.usc+(e.key==='ArrowRight'?1:3))%4;renderUSC();$(`[data-usc="${state.usc}"]`).focus()}});
addUSCWorkshop();renderInterests();renderPlan();renderQuest();renderAI();renderUSC();go(location.hash.slice(1)||'home',false);

document.addEventListener('input',e=>{if(e.target.dataset.questReason!==undefined)state.questNotes[Number(e.target.dataset.questReason)]=e.target.value;if(e.target.dataset.reflection){const key=e.target.dataset.reflection;state.reflection[key]=e.target.value;const out=$(`[data-reflection-print="${key}"]`);if(out)out.textContent=e.target.value||'Not added';updateExportButtons()}});
